def two_sum_pair(values, target):
    """Return the lexicographically smallest index pair (i, j) with i < j
    and values[i] + values[j] == target, or None when no pair exists.

    Accepts one-shot iterables and does not mutate inputs.
    Every value and the target must be an actual integer, not a boolean;
    invalid inputs raise ValueError.
    """
    # Validate target
    if not isinstance(target, int) or isinstance(target, bool):
        raise ValueError("target must be an integer")

    # Validate values iterable
    if not hasattr(values, '__iter__'):
        raise ValueError("values must be an iterable")

    # Convert to list to allow multiple passes and index access
    # This also validates all elements
    values_list = list(values)

    # Validate all elements
    for v in values_list:
        if not isinstance(v, int) or isinstance(v, bool):
            raise ValueError("all values must be integers")

    # Find all valid pairs and return the lexicographically smallest
    best = None
    n = len(values_list)
    for i in range(n):
        for j in range(i + 1, n):
            if values_list[i] + values_list[j] == target:
                if best is None or (i, j) < best:
                    best = (i, j)
    return best

