from collections.abc import Mapping

def expand_template(template, values):
    """Replace ${name} placeholders with str(values[name]) and turn $$ into one literal dollar sign.

    Names use ASCII letters, digits, and underscores and cannot begin with a digit.
    Repeated placeholders are supported. Missing names raise KeyError; malformed templates,
    non-string templates, or non-mapping values raise ValueError. No environment variables are read.

    Args:
        template: A string containing placeholders to expand.
        values: A mapping from placeholder names to values.

    Returns:
        The expanded string.

    Raises:
        KeyError: If a placeholder name is not found in values.
        ValueError: If the template is malformed, not a string, or values is not a mapping.
    """
    if not isinstance(template, str):
        raise ValueError("template must be a string")
    if not isinstance(values, Mapping):
        raise ValueError("values must be a mapping")

    result = []
    i = 0
    while i < len(template):
        if template[i:i+2] == '$$':
            result.append('$')
            i += 2
        elif template[i] == '$':
            if i + 1 >= len(template):
                raise ValueError("trailing $ in template")
            if template[i+1] == '{':
                # Find the closing brace
                j = template.find('}', i + 2)
                if j == -1:
                    raise ValueError("unclosed ${ in template")
                name = template[i+2:j]
                # Validate name: ASCII letters, digits, underscores, cannot begin with digit
                if not name or not all(c.isascii() and (c.isalnum() or c == '_') for c in name):
                    raise ValueError(f"invalid placeholder name: {name!r}")
                if name[0].isdigit():
                    raise ValueError(f"placeholder name cannot begin with digit: {name!r}")
                if name not in values:
                    raise KeyError(name)
                result.append(str(values[name]))
                i = j + 1
            elif template[i+1] == '$':
                result.append('$')
                i += 2
            else:
                raise ValueError(f"malformed template: ${template[i+1]!r}")
            name = template[i+2:j]
            # Validate name: ASCII letters, digits, underscores, cannot begin with digit
            if not name or not all(c.isascii() and (c.isalnum() or c == '_') for c in name):
                raise ValueError(f"invalid placeholder name: {name!r}")
            if name[0].isdigit():
                raise ValueError(f"placeholder name cannot begin with digit: {name!r}")
            if name not in values:
                raise KeyError(name)
            result.append(str(values[name]))
            i = j + 1
        else:
            result.append(template[i])
            i += 1
    return ''.join(result)

