def histogram(values, boundaries):
    """Return a list of counts for each boundary bucket given `values` and `boundaries`.

    `histogram(values, boundaries)` returns `len(boundaries) + 1` counts. For boundaries
    `[b0, b1]`, buckets are `(-inf, b0]`, `(b0, b1]`, and `(b1, inf)`: a value equal to a
    boundary belongs to the lower bucket. Boundaries must be finite, strictly increasing
    numbers; values must be finite numbers. Booleans are not numbers here. Invalid input
    raises `ValueError`, and inputs are not mutated.
    """
    if not isinstance(values, list):
        raise ValueError("values must be a list")
    if not isinstance(boundaries, list):
        raise ValueError("boundaries must be a list")
    if len(boundaries) == 0:
        raise ValueError("boundaries must not be empty")
    for b in boundaries:
        if not isinstance(b, (int, float)):
            raise ValueError("boundaries must contain only numbers")
        if not math.isfinite(b):
            raise ValueError("boundaries must be finite")
    for i in range(len(boundaries) - 1):
        if boundaries[i] >= boundaries[i + 1]:
            raise ValueError("boundaries must be strictly increasing")
    for v in values:
        if not isinstance(v, (int, float)):
            raise ValueError("values must contain only numbers")
        if isinstance(v, bool):
            raise ValueError("values must not contain booleans")
        if not math.isfinite(v):
            raise ValueError("values must be finite")
    counts = [0] * (len(boundaries) + 1)
    for v in values:
        for i, b in enumerate(boundaries):
            if v <= b:
                counts[i] += 1
                break
        else:
            counts[-1] += 1
    return counts

