def mapping_diff(before, after):
    """Return a dict with keys "added", "removed", and "changed" that
    represent the shallow diff of two mappings.

    Added values come from `after`, removed values from `before`, and changed
    entries map each key to (before_value, after_value). Compare values
    shallowly with ==; omit unchanged keys. Each section's string keys must be
    inserted in sorted order. Inputs must be mappings with string keys, must not
    be mutated, and invalid input raises ValueError.

    >>> mapping_diff({"a": 1, "b": 2}, {"a": 1, "c": 3})
    {'added': {'c': 3}, 'removed': {'b': 2}, 'changed': {}}
    >>> mapping_diff({"a": 1, "b": 2}, {"a": 10, "c": 3})
    {'added': {'c': 3}, 'removed': {'b': 2}, 'changed': {'a': (1, 10)}}
    >>> mapping_diff({"a": 1, "b": 2}, {"a": 1, "b": 2})
    {'added': {}, 'removed': {}, 'changed': {}}
    """
    if not isinstance(before, dict) or not isinstance(after, dict):
        raise ValueError("Inputs must be mappings")
    if not all(isinstance(k, str) for k in before) or not all(isinstance(k, str) for k in after):
        raise ValueError("Keys must be strings")

