def max_concurrent(events):
    """Return the greatest number of overlapping half-open integer intervals (start, end).
    An interval ending when another starts does not overlap it.
    Require start < end for every interval or raise ValueError;
    an empty input returns 0."""
    if not events:
        return 0
    for start, end in events:
        if start >= end:
            raise ValueError("start must be less than end")
    # Create events: (time, type) where type is +1 for start, -1 for end
    # For half-open intervals, an end at time t does not overlap a start at time t.
    # So we process ends before starts at the same time.
    events_list = []
    for start, end in events:
        events_list.append((start, 1))   # start event
        events_list.append((end, -1))    # end event
    # Sort by time; for same time, end events (-1) come before start events (+1)
    events_list.sort(key=lambda x: (x[0], x[1]))
    current = 0
    max_conc = 0
    for time, etype in events_list:
        current += etype
        if current > max_conc:
            max_conc = current
    return max_conc

